entries[448247] = { ["name"] = "Abstoßende Salve", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde schleudert eine widerwärtige Mischung aus Blut und Gift auf alle Spielercharaktere in der Nähe sowie Schmutz auf einen zufälligen Spielercharakter und verursacht so 14 Naturschaden. Die blubbernde Flüssigkeit bleibt an den getroffenen Zielen kleben, verursacht alle 1 Sek. 3 Naturschaden und absorbiert die nächsten 10 Heilung." }
