entries[448658] = { ["name"] = "Anrufung: Arkaner Phönix", ["text"] = "Arkan\nWenn Ihr 'Arkane Woge' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n' Arkaner Phönix '\nEuer arkaner Phönix unterstützt Euch für die Dauer von 'Arkane Woge' und setzt zufällige arkane und Feuerzauber ein.\n\nFeuer\nWenn Ihr 'Einäschern' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n' Arkaner Phönix '\nEuer arkaner Phönix unterstützt Euch für die Dauer von 'Einäschern' und setzt zufällige arkane und Feuerzauber ein." }
entries[448659] = { ["name"] = "Arkaner Phönix", ["text"] = "40 Meter Reichweite\nSofort\nArkan\nWenn Ihr 'Arkane Woge' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n' Arkaner Phönix '\nEuer arkaner Phönix unterstützt Euch für die Dauer von 'Arkane Woge' und setzt zufällige arkane und Feuerzauber ein.\n\nFeuer\nWenn Ihr 'Einäschern' einsetzt, beschwört Ihr einen arkanen Phönix, der Euch im Kampf unterstützt.\n\n' Arkaner Phönix '\nEuer arkaner Phönix unterstützt Euch für die Dauer von 'Einäschern' und setzt zufällige arkane und Feuerzauber ein." }
