entries[448669] = { ["name"] = "Phantomernte", ["text"] = "100 Meter Reichweite\nSofort\nEure Fähigkeiten haben eine hohe Chance, ein Phantom zu beschwören, das Eurem Ziel ( 1 * 600 ) Schattenschaden und allen anderen Gegnern in seinem Weg ( 1 * 600 * 0.09) Schattenschaden zufügt.\n\nWenn sich das Ziel bei weniger als 35% Gesundheit befindet, beschwört dieser Effekt zwei zusätzliche Phantome mit 25% Effektivität." }
