entries[448680] = { ["name"] = "Unterkrabbler der Witwe", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Kinder an der Oberfläche träumen oft vom eigenen Pony oder Wolf, wenn sie ein bestimmtes Alter erreichen. Die junge Witwe Arak'nai hatte ähnliche Ambitionen, auch wenn ihr Geschmack gemäß anderen Standards eher als eklektisch gelten dürfte.\"\nVerkäufer:\nYamas der Ernährer, Hüppi\nZone:\nAzj-Kahet\nKosten:\n2020" }
