entries[448685] = { ["name"] = "Erbunterkrabbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Haltung von Arachniden ist eine altbewährte Tradition der Erbmächte. Auch wenn die meisten Exemplare für Transportzwecke oder als Schocktruppen eingesetzt werden, schaffen es die besten Exemplare gelegentlich auch zum Paradereittier.\"\nVerkäufer:\nYamas der Ernährer, Anub'okki, Aspirant Kiipka\nZone:\nAzj-Kahet\nKosten:\n2020" }
entries[448689] = { ["name"] = "Unterkrabbler des königlichen Hofs", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Abstammungsbriefe werden verwendet, um in den gehobenen Kreisen der Kaheti die Herkunft und den Wert vollblütiger Unterkrabbler nachzuweisen. Dieses Verfahren kann sich allerdings als schwieriger als gedacht herausstellen, da eben jene Unterkrabbler dafür anfällig sind, plötzlich von ihren Verwaltern verspeist zu werden.\"\nVerkäufer:\nYamas der Ernährer, Tulumun\nZone:\nAzj-Kahet\nKosten:\n2020" }
