entries[449349] = { ["name"] = "Sonnenzornhinrichtung", ["text"] = "Arkan\nErhöht den Bonusschaden von 'Arkanes Bombardement' auf 130%.\n\n' Arkanes Bombardement '\n'Arkanbeschuss' fügt Zielen mit weniger als 35% Gesundheit 100% mehr Schaden zu.\n\nFeuer\nErhöht den Schwellenwert des kritischen Schadens von 'Versengen' auf 35%.\n\n' Versengen '\nVersengt einen Gegner und fügt ihm (30% der Zaubermacht) Feuerschaden zu.\n\n'Versengen' trifft beim Einsatz gegen ein Ziel mit weniger als 30% Gesundheit garantiert kritisch und erhöht Eure Bewegungsgeschwindigkeit 3 Sek. lang um 30%.\n\nKann aus der Bewegung heraus eingesetzt werden." }
