entries[449412] = { ["name"] = "Den Moment genießen", ["text"] = "Arkan\nWenn Ihr 'Arkane Woge' wirkt, wird die Dauer dieses Zaubers um 0.5 Sek. für jede Zauberfeuersphäre in Eurem Besitz und maximal bis auf 2.5 Sek. verlängert.\n\nFeuer\nWenn Ihr 'Einäschern' wirkt, wird die Dauer dieses Zaubers um 0.5 Sek. für jede Zauberfeuersphäre in Eurem Besitz und maximal bis auf 2.5 Sek. verlängert." }
