entries[449541] = { ["name"] = "Blutiger Haken des Tiefenjägers", ["text"] = "Ca. 3 Procs pro Minute\nEure Nahkampfangriffe haben eine Chance einen blutigen Haken am Ziel zu verankern. Nach 4 Sek. wird der Haken zurückgezogen und das Ziel erleidet ( 1 * 836 ) körperlichen Schaden.\n\nSolange das Ziel am Haken ist, wird dieser durch jeden kritischen körperlichen Treffer tiefer verankert, was im Verlauf von 8 Sek. ( 1 * 118 ) zusätzlichen körperlichen Schaden verursacht." }
