entries[449563] = { ["name"] = "Nerubischer Giftpfeil", ["text"] = "Ca. 3 Procs pro Minute\nEure Distanzangriffe haben eine Chance dem Ziel ein lähmendes Gift zu injizieren, das im Verlauf von 9 Sek. ( 1 * 592 ) Naturschaden verursacht.\n\nFür jede Sekunde, in der sich das betroffene Ziel bewegt, erhaltet Ihr 10 Sek. lang ( 24 / 5) Tempo. Bis zu 5-mal stapelbar." }
entries[449564] = { ["name"] = "Reparierende Flammen", ["text"] = "10 Meter Reichweite\nSofort 10 sek. Abklingzeit\nErschafft einen Schild, der Euch vor jeglichem Schaden schützt und Euch schnell auf volle Gesundheit heilt. Hält 4 Sek. lang an." }
entries[449566] = { ["name"] = "Meteoritenbrand", ["text"] = "100 Meter Reichweite\nSofort\nRuft einen Meteor herab, der nach 3 Sek. am Zielort einschlägt. Fügt allen Gegnern (444% der Zaubermacht) Feuerschaden zu und verbrennt den Boden, um allen Gegnern im Gebiet im Verlauf von 8.5 Sek. [8 * (8.53875% der Zaubermacht)] Feuerschaden zuzufügen.\n\nDer Gegner, der am nächsten zum Zentrum des Einschlags ist, erleidet 40% mehr Schaden. Der Schaden ist nach dem 8. Ziel verringert." }
entries[449567] = { ["name"] = "Filetieren", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nSchneidet einen Feind und fügt ihm 150% Waffenschaden als körperlichen Schaden zu." }
entries[449568] = { ["name"] = "Netzblitz", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde feuert einen dichten Klumpen aus Spinnweben auf sein aktuelles Ziel, der diesem Naturschaden zufügt und seine Bewegungsgeschwindigkeit 5 Sek. lang um 30% verringert." }
