entries[449614] = { ["name"] = "Dämonenseele", ["text"] = "Dämonologie\nEin dämonisches Wesen wohnt in Eurer Seele und ermöglicht es Euch zu entdecken, ob ein Seelensplitter bei seiner Entstehung über eine saftige Seele verfügt.\n\nEine saftige Seele ermächtigt Euren nächsten Einsatz von 'Hand von Gul'dan', erhöht seinen Schaden um 60% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen.\n\nGebrechen\nEin dämonisches Wesen wohnt in Eurer Seele und ermöglicht es Euch zu entdecken, ob ein Seelensplitter bei seiner Entstehung über eine saftige Seele verfügt.\n\nEine saftige Seele ermächtigt Euren nächsten Einsatz von 'Unheilvolle Euphorie', erhöht seinen Schaden um 20% und entfesselt Eure dämonische Seele, um (176.618% der Zaubermacht) zusätzlichen Schattenschaden zu verursachen." }
entries[449619] = { ["name"] = "Erinnerung an Al'ar", ["text"] = "Arkan\nWährend Ihr unter dem Effekt von 'Arkane Woge' steht, erhaltet Ihr doppelt so viele Stapel von 'Manakaskade'.\n\nWenn Euer arkaner Phönix abläuft, ermächtigt er Euch und verleiht Euch 'Arkane Seele' für 2 Sek. und weitere 1.0 Sek. pro außergewöhnlichem Zauber, der zum Einsatz gekommen ist.\n\nArkane Seele :\n'Arkanbeschuss' gewährt 'Freizaubern' und erzeugt 4 arkane Aufladungen.\n\nJedes Wirken von 'Arkanbeschuss' erhöht den Schaden von 'Arkanbeschuss' um 15%, bis maximal 150%.\n\nFeuer\nWährend Ihr unter dem Effekt von 'Einäschern' steht, erhaltet Ihr doppelt so viele Stapel von 'Manakaskade'.\n\nWenn Euer arkaner Phönix abläuft, ermächtigt er Euch und verleiht Euch 'Hyperthermie' für 2 Sek. und weitere 1.0 Sek. pro außergewöhnlichem Zauber, der zum Einsatz gekommen ist.\n\nHyperthermie :\n'Pyroschlag' und 'Flammenstoß' sind Spontanzauber, erzielen garantiert kritische Treffer und erhöhen den Schaden von 'Pyroschlag' und 'Flammenstoß' um 15%." }
entries[449620] = { ["name"] = "Nekrolythenlehren", ["text"] = "Gebrechen\n'Schattenblitz' und 'Seelendieb' um 20% erhöht. 'Nachtsturz' erhöht den Schaden von 'Schattenblitz' und 'Seelendieb' um zusätzliche 50%.\n\nDämonologie\nSchaden von 'Schattenblitz' um 20% erhöht. 'Kraftentzug' erhöht den Schaden von 'Dämonenblitz' um zusätzliche 20%." }
entries[449621] = { ["name"] = "Erinnerungen kombinieren", ["text"] = "Wirken in 5 sek.\nReagenzien:\nErinnerung an Nordend (20)\nKombinieren 20 Erinnerungen von Nordend in eine verfestigte Essenz." }
entries[449622] = { ["name"] = "Netzsprechen", ["text"] = "Sofort\nIhr zapft ein Netz aus uraltem Wissen an und erhöht Euer Zaubertempo 15 Sek. lang um 25%." }
entries[449623] = { ["name"] = "Erinnerungen kombinieren", ["text"] = "Wirken in 5 sek.\nReagenzien:\nErinnerung an Kalimdor (20)\nKombinieren 20 Erinnerungen von Kalimdor in eine verfestigte Essenz." }
entries[449624] = { ["name"] = "Seelenbannfluch", ["text"] = "Das Entfesseln Eurer dämonischen Seele überträgt ein teuflisches Wesen auf die Seele ihrer Ziele und fügt ihnen im Verlauf von 10 Sek. (127.457% der Zaubermacht) Schattenschaden zu.\n\nWird dieser Effekt erneut angewendet, wird verbleibender Schaden dem neuen 'Seelenbannfluch' hinzugefügt." }
entries[449625] = { ["name"] = "Umarmung der Leere" }
entries[449626] = { ["name"] = "Minischlange des Astralkaisers", ["text"] = "Sofort\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben." }
entries[449627] = { ["name"] = "Lektionen in Entkräftung", ["text"] = "Euer arkaner Phönix wendet 'Zauberraub' an, wenn er beschworen wird und wenn er abläuft." }
entries[449628] = { ["name"] = "Erinnerungen kombinieren", ["text"] = "Wirken in 5 sek.\nReagenzien:\nErinnerung an die Östlichen Königreiche (20)\nKombinieren 20 Erinnerungen der Östlichen Königreiche in eine verfestigte Essenz." }
entries[449629] = { ["name"] = "Eifer des Besessenen", ["text"] = "Dämonologie\nEure dämonische Seele fügt dem Hauptziel von 'Hand von Gul'dan' 100% mehr Schaden zu.\n\nGebrechen\nEure dämonische Seele fügt von Eurem Zauber 'Instabiles Gebrechen' betroffenen Zielen 100% mehr Schaden zu." }
entries[449631] = { ["name"] = "Tückischer Schnitter", ["text"] = "Dämonologie\nDer von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\nDer Verbrauch von 'Dämonischer Kern' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel [(240.402% der Zaubermacht) * 0.4] Schattenschaden zufügt.\n\nGebrechen\nDer von Eurer dämonischen Seele verursachte Schaden wird um 10% erhöht.\n\nDer Verbrauch von 'Nachtsturz' füttert das dämonische Wesen in Euch, das erscheint und Eurem Ziel (240.402% der Zaubermacht) Schattenschaden zufügt." }
entries[449632] = { ["name"] = "Erinnerung aufnehmen" }
entries[449634] = { ["name"] = "Exitus", ["text"] = "Dämonologie\nDer Schaden von 'Seelenbannfluch' wird um 25% erhöht und um 20% schneller verursacht.\n\nDer Verbrauch von 'Dämonischer Kern' aktiviert 'Geteiltes Schicksal' oder 'Festmahl der Seelen'.\n\nGebrechen\nDer Schaden von 'Seelenbannfluch' wird um 25% erhöht und um 20% schneller verursacht.\n\nDer Verbrauch von 'Nachtsturz' aktiviert 'Geteiltes Schicksal' oder 'Festmahl der Seelen'." }
entries[449637] = { ["name"] = "Sataiels Wille", ["text"] = "Gebrechen\n'Verderbnis' verursacht Schaden um 25% schneller, und 'Heimsuchung' gewährt 'Nachtsturz'.\n\nDämonologie\nDer Schaden von Wildwichteln wird um 5% erhöht, und implodierte Wildwichtel haben eine zusätzliche Chance von 5%, Euch 'Dämonischer Kern' zu gewähren." }
entries[449638] = { ["name"] = "Schatten des Todes", ["text"] = "Dämonologie\nEuer Zauber 'Dämonischen Tyrannen beschwören' ist vom dämonischen Wesen in Euch ermächtigt, sodass er Euch 3 Seelensplitter gewährt, die jeweils eine saftige Seele enthalten.\n\nGebrechen\nEuer Zauber 'Seelenfäule' ist vom dämonischen Wesen in Euch ermächtigt, sodass er Euch 3 Seelensplitter gewährt, die jeweils eine saftige Seele enthalten." }
entries[449639] = { ["name"] = "Erinnerungen durchtränken", ["text"] = "Wirken in 5 sek.\nReagenzien:\nEssenz der Östlichen Königreiche , Essenz Kalimdors , Essenz Nordends , Lebloser Steinring\nDurchtränke sie mit den Essenzen Azeroths, um ihre Macht wiederherzustellen." }
