entries[449666] = { ["name"] = "Uraltes Waffenöl", ["text"] = "Brann verzaubert vorübergehend für 10 Sek. die Waffe eines Spielercharakters in der Nähe, sodass dessen Zauber und Fähigkeiten zusätzlichen Schaden als Feuerschaden verursachen, solange er in einen Kampf verwickelt bleibt.\n\nWenn die Verzauberung entfernt wird, springt der Effekt auf einen Verbündeten in der Nähe über." }
entries[449667] = { ["name"] = "Dunkelheit naht", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchattenkrone entfesselt eine massive Explosion von Schattenmagie und versucht, alle Spielercharaktere an Bord der Morgenbringer zu vernichten. Beim Wirken ist Schattenkrone immun gegen Schaden." }
entries[449682] = { ["name"] = "Schattig" }
entries[449684] = { ["name"] = "Strahlendes Licht", ["text"] = "Unbegrenzte Reichweite\nSofort\nSegnet alle in der Nähe mit ' Strahlendes Licht '.\n\nStrahlendes Licht\nUnbegrenzte Reichweite\n\nSofort Strahlendes Licht umhüllt den Spielercharakter und schützt ihn vor ' Wuchernde Schatten '. Erlaubt Himmelsreiten, statisches Fliegen und Aufsitzen im Kampf.\n\nSobald der Einflussbereich des Lampenanzünders verlassen wird, hält 'Strahlendes Licht' nicht mehr ewig an. Wenn 10 Sek. oder weniger Zeit verbleibt, erleiden Spielercharaktere ' Wuchernde Schatten '." }
entries[449685] = { ["name"] = "Wuchernde Schatten", ["text"] = "Kanalisiert (Wirken in 7 tagen)\nDas Ritual des Ordens der Nacht auf Beledar fügt allen, die nicht durch ' Strahlendes Licht ' geschützt sind, 242444938 Schattenschaden zu, was bei Ablauf des Effekts zum sofortigen Tode führt." }
entries[449686] = { ["name"] = "Strahlendes Licht" }
entries[449687] = { ["name"] = "Geschmolzener Streitkolben", ["text"] = "Wirken in 2.5 sek. 3 sek. Abklingzeit\nThorngus schmiedetet einen riesigen Streitkolben aus Lava, wodurch er für 10 Sek. 1000% mehr Nahkampfschaden verursacht." }
entries[449689] = { ["name"] = "Geschmolzene Welle" }
entries[449690] = { ["name"] = "Zwillingsklingenstoß", ["text"] = "40 Meter Reichweite\nWirken in 1.5 sek. 3.5 sek. Abklingzeit\nDie Königswache greift mit beiden Klingen an und fügt dem Ziel 1151263 Naturschaden und 1151263 Schattenschaden zu." }
entries[449693] = { ["name"] = "Abschreckendes Heulen", ["text"] = "60 Meter Reichweite\nWirken in 2 sek. 4 sek. Abklingzeit\nDer Zaubernde heult, fügt Spielercharakteren innerhalb von 60 Metern so 1151263 Schattenschaden zu und lässt sie 6 Sek. lang furchterfüllt auf den Zaubernden zulaufen." }
entries[449696] = { ["name"] = "Verheerende Schreckenswelle", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde entfesselt eine Welle schattenhafter Verwüstung, die Spielercharakteren vor dem Zaubernden 2302526 Schattenschaden zufügt und sie zurückstößt." }
entries[449697] = { ["name"] = "Durchdrungene Klingen", ["text"] = "Sofort\nAngriffe mit der Waffenhand lösen ' Wunde der Giftklinge ' aus und verursachen für 10 Sek. alle 0.5 Sek. 57563 Naturschaden.\n\nSchildhandangriffe lösen ' Wunde der Leerenklinge ' aus und fügen Verbündeten im Umkreis von 4 Metern für 9 Sek. alle 1.5 Sek. 287816 Schattenschaden zu." }
entries[449698] = { ["name"] = "Wunde der Giftklinge", ["text"] = "100 Meter Reichweite\nSofort\nAngriffe mit der Waffenhand lösen ' Wunde der Giftklinge ' aus und verursachen für 10 Sek. alle 0.5 Sek. 57563 Naturschaden.\n\nSchildhandangriffe lösen ' Wunde der Leerenklinge ' aus und fügen Verbündeten im Umkreis von 4 Metern für 9 Sek. alle 1.5 Sek. 287816 Schattenschaden zu." }
entries[449699] = { ["name"] = "Neruber" }
entries[449700] = { ["name"] = "Gravitationsverlust", ["text"] = "40 Meter Reichweite\nSofort 40 sek. Abklingzeit\nMit einem Fingerschnippen verzerrt Ihr die Schwerkraft um Euer Ziel sowie 4 weitere Gegner in der Nähe und lasst sie 3 Sek. lang in der Luft schweben.\nBei ihrer Landung erleiden Gegner in der Nähe (50% der Zaubermacht) Arkanschaden." }
entries[449701] = { ["name"] = "Blutige Seelenstärke", ["text"] = "Beim Verbrauchen eines Gesundheitssteins erhaltet Ihr stets den Vorteil von 'Seelenbrand', dessen Heilung um 30% erhöht wird. Außerdem steigt Eure maximale Gesundheit 12 Sek. lang um 20%." }
entries[449702] = { ["name"] = "Triefender Honig", ["text"] = "Kanalisiert (Wirken in 20 sek.)\nBräutropfen sondert beim Tod brennenden Honig ab, der Spielercharakteren darin alle 1.5 Sek. 2909339 Feuerschaden zufügt und ihre Bewegungsgeschwindigkeit um 50% verringert.\n\nDie Honiglache schrumpft mit der Zeit." }
entries[449703] = { ["name"] = "Freunde an dunklen Orten", ["text"] = "'Dunkler Pakt' schirmt Euch nun für zusätzliche 50% der geopferten Gesundheit ab." }
entries[449704] = { ["name"] = "Geteiltes Schicksal", ["text"] = "Wenn Ihr ein Ziel tötet, wird dessen gequälte Seele 3 Sek. lang in einen nahen Gegner geschleudert. Dieser Effekt fügt Gegnern innerhalb von 10 Metern alle 1 Sek. (50.6531% der Zaubermacht) Schattenschaden zu.\n\nVerursacht bei Zielen über 8 Ziele hinaus verringerten Schaden." }
entries[449705] = { ["name"] = "Wunde der Leerenklinge", ["text"] = "100 Meter Reichweite\nSofort\nAngriffe mit der Waffenhand lösen ' Wunde der Giftklinge ' aus und verursachen für 10 Sek. alle 0.5 Sek. 57563 Naturschaden.\n\nSchildhandangriffe lösen ' Wunde der Leerenklinge ' aus und fügen Verbündeten im Umkreis von 4 Metern für 9 Sek. alle 1.5 Sek. 287816 Schattenschaden zu." }
entries[449706] = { ["name"] = "Festmahl der Seelen", ["text"] = "Wenn Ihr ein Ziel tötet, besteht die Chance, dass Ihr einen Seelensplitter erzeugt, der garantiert eine saftige Seele ist." }
entries[449707] = { ["name"] = "Ewige Knechtschaft", ["text"] = "Verringert die Abklingzeit von 'Teufelsbeherrschung' um 90 Sek." }
entries[449709] = { ["name"] = "Wasserschlag", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDas aktuelle Ziel wird mit Wasser überspült, erleidet Frostschaden und verringert den von ihm verursachten Schaden für 5 Sek. um 10%." }
entries[449710] = { ["name"] = "Amulett der Untergrundbestie", ["text"] = "Sofort\nEure Zauber haben eine Chance, die animalischen Erkenntnisse des Amuletts wachzurufen, die Euren kritischen Trefferwert 12 Sek. lang um 105 erhöhen.\n\nWenn Ihr gegen ein Tier oder an der Seite eines Tiers kämpft, ist dieser Effekt um 20% erhöht." }
